import { useMemo, useState } from "react";
import { Pressable, ScrollView, StyleSheet, Text, View } from "react-native";
import Svg, { Line, Polygon, Rect, Text as SvgText } from "react-native-svg";
import { radii, spacing, useKeatingTheme } from "@/constants/theme";
import { parseMermaidFlowchart } from "@/lib/mermaid-native";

const NODE_WIDTH = 132;
const NODE_HEIGHT = 48;

export function MermaidDiagram({ source }: { source: string }) {
  const theme = useKeatingTheme();
  const styles = createStyles(theme);
  const graph = useMemo(() => parseMermaidFlowchart(source), [source]);
  const [sourceOpen, setSourceOpen] = useState(false);
  if (!graph) return <DiagramFallback source={source} reason="This Mermaid diagram uses syntax the native renderer does not support yet." />;
  const levels = new Map<number, typeof graph.nodes>();
  graph.nodes.forEach((node) => levels.set(node.level, [...(levels.get(node.level) ?? []), node]));
  const maxAcross = Math.max(...[...levels.values()].map((nodes) => nodes.length));
  const maxLevel = Math.max(...graph.nodes.map((node) => node.level));
  const width = graph.direction === "LR" ? (maxLevel + 1) * 180 : Math.max(320, maxAcross * 156);
  const height = graph.direction === "LR" ? Math.max(132, maxAcross * 84) : (maxLevel + 1) * 92;
  const positions = new Map<string, { x: number; y: number }>();
  for (const [level, nodes] of levels) {
    nodes.forEach((node, index) => {
      const x = graph.direction === "LR" ? 24 + level * 180 : (width - nodes.length * 156) / 2 + index * 156 + 12;
      const y = graph.direction === "LR" ? 20 + index * 84 : 20 + level * 92;
      positions.set(node.id, { x, y });
    });
  }
  return (
    <View style={styles.frame}>
      <ScrollView horizontal showsHorizontalScrollIndicator contentContainerStyle={styles.scroller}>
        <Svg accessibilityRole="image" accessibilityLabel={`Flowchart with ${graph.nodes.length} nodes and ${graph.edges.length} connections`} width={width} height={height}>
          {graph.edges.map((edge, index) => {
            const from = positions.get(edge.from)!;
            const to = positions.get(edge.to)!;
            const startX = graph.direction === "LR" ? from.x + NODE_WIDTH : from.x + NODE_WIDTH / 2;
            const startY = graph.direction === "LR" ? from.y + NODE_HEIGHT / 2 : from.y + NODE_HEIGHT;
            const endX = graph.direction === "LR" ? to.x : to.x + NODE_WIDTH / 2;
            const endY = graph.direction === "LR" ? to.y + NODE_HEIGHT / 2 : to.y;
            const arrow = graph.direction === "LR"
              ? `${endX},${endY} ${endX - 8},${endY - 5} ${endX - 8},${endY + 5}`
              : `${endX},${endY} ${endX - 5},${endY - 8} ${endX + 5},${endY - 8}`;
            return <View key={`${edge.from}-${edge.to}-${index}`}>
              <Line x1={startX} y1={startY} x2={endX} y2={endY} stroke={theme.colors.primaryText} strokeWidth={2} />
              <Polygon points={arrow} fill={theme.colors.primaryText} />
              {edge.label ? <SvgText x={(startX + endX) / 2} y={(startY + endY) / 2 - 5} fill={theme.colors.textMuted} fontSize={11} textAnchor="middle">{truncate(edge.label, 18)}</SvgText> : null}
            </View>;
          })}
          {graph.nodes.map((node) => {
            const position = positions.get(node.id)!;
            return <View key={node.id}>
              <Rect x={position.x} y={position.y} width={NODE_WIDTH} height={NODE_HEIGHT} rx={8} fill={theme.colors.surfaceRaised} stroke={theme.colors.borderStrong} strokeWidth={1} />
              <SvgText x={position.x + NODE_WIDTH / 2} y={position.y + 29} fill={theme.colors.text} fontSize={12} textAnchor="middle">{truncate(node.label, 22)}</SvgText>
            </View>;
          })}
        </Svg>
      </ScrollView>
      <Pressable accessibilityRole="button" accessibilityState={{ expanded: sourceOpen }} onPress={() => setSourceOpen((current) => !current)} style={({ pressed }) => [styles.sourceButton, pressed && styles.pressed]}>
        <Text style={styles.sourceLabel}>{sourceOpen ? "Hide diagram source" : "Show diagram source"}</Text>
      </Pressable>
      {sourceOpen ? <Text selectable style={styles.source}>{source}</Text> : null}
    </View>
  );
}

function DiagramFallback({ source, reason }: { source: string; reason: string }) {
  const styles = createStyles(useKeatingTheme());
  return <View style={styles.frame}><Text style={styles.fallback}>{reason}</Text><Text selectable style={styles.source}>{source}</Text></View>;
}

function truncate(value: string, limit: number): string { return value.length <= limit ? value : `${value.slice(0, limit - 1)}…`; }

function createStyles(theme: ReturnType<typeof useKeatingTheme>) {
  const { colors, type } = theme;
  return StyleSheet.create({
    frame: { marginVertical: spacing.md, overflow: "hidden", borderRadius: radii.md, borderWidth: 1, borderColor: colors.border, backgroundColor: colors.backgroundDeep },
    scroller: { padding: spacing.sm },
    sourceButton: { minHeight: 44, justifyContent: "center", paddingHorizontal: spacing.md, borderTopWidth: 1, borderTopColor: colors.border },
    sourceLabel: { ...type.caption, color: colors.primaryText },
    source: { ...type.caption, ...type.mono, color: colors.textMuted, lineHeight: 19, padding: spacing.md },
    fallback: { ...type.caption, color: colors.warning, lineHeight: 19, paddingHorizontal: spacing.md, paddingTop: spacing.md },
    pressed: { backgroundColor: colors.surfacePressed },
  });
}

export interface MermaidNode { id: string; label: string; level: number }
export interface MermaidEdge { from: string; to: string; label?: string }
export interface MermaidFlowchart { direction: "TD" | "LR"; nodes: MermaidNode[]; edges: MermaidEdge[] }

const NODE = String.raw`([A-Za-z0-9_.-]+)(?:\[([^\]]*)\]|\(([^)]*)\)|\{([^}]*)\})?`;
const EDGE = new RegExp(`^\\s*${NODE}\\s*(?:-->|---|-.->|==>)\\s*(?:\\|([^|]+)\\|\\s*)?${NODE}\\s*$`);
const DECLARATION = new RegExp(`^\\s*${NODE}\\s*$`);

/** A bounded native renderer for the flowcharts Keating emits most often. */
export function parseMermaidFlowchart(source: string): MermaidFlowchart | null {
  if (source.length > 16_384) return null;
  const statements = source.split(/[;\n]+/).map((line) => line.trim()).filter(Boolean);
  const header = statements.shift()?.match(/^(?:graph|flowchart)\s+(TD|TB|LR|RL)$/i);
  if (!header) return null;
  const direction = /LR|RL/i.test(header[1]) ? "LR" : "TD";
  const labels = new Map<string, string>();
  const edges: MermaidEdge[] = [];
  const addNode = (id: string, ...possible: Array<string | undefined>) => labels.set(id, possible.find((value) => value?.trim())?.trim() ?? labels.get(id) ?? id);
  for (const statement of statements) {
    if (/^(?:classDef|class|style|linkStyle|click|subgraph|end)\b/i.test(statement)) return null;
    const edge = statement.match(EDGE);
    if (edge) {
      const [from, fromBox, fromRound, fromDiamond, edgeLabel, to, toBox, toRound, toDiamond] = edge.slice(1);
      addNode(from!, fromBox, fromRound, fromDiamond);
      addNode(to!, toBox, toRound, toDiamond);
      edges.push({ from: from!, to: to!, ...(edgeLabel?.trim() ? { label: edgeLabel.trim() } : {}) });
      continue;
    }
    const declaration = statement.match(DECLARATION);
    if (!declaration) return null;
    addNode(declaration[1]!, declaration[2], declaration[3], declaration[4]);
  }
  if (!labels.size || labels.size > 48 || edges.length > 96) return null;
  const levels = new Map([...labels.keys()].map((id) => [id, 0]));
  for (let pass = 0; pass < labels.size; pass += 1) {
    let changed = false;
    for (const edge of edges) {
      const next = Math.min(labels.size - 1, (levels.get(edge.from) ?? 0) + 1);
      if (next > (levels.get(edge.to) ?? 0)) { levels.set(edge.to, next); changed = true; }
    }
    if (!changed) break;
  }
  return {
    direction,
    nodes: [...labels].map(([id, label]) => ({ id, label, level: levels.get(id) ?? 0 })),
    edges,
  };
}

