import { useState } from "react";
import type { UiDocument, UiDocumentNode, UiQuestion, UiStudyPlanItem } from "@keating/learner-contracts";
import { css } from "../../../styled-system/css";
import { MarkdownBlock } from "../../components/MarkdownBlock";
import { MermaidRenderer } from "../../components/MermaidRenderer";

export interface SharedUiActionEvent {
	type: string;
	humanFriendlyMessage: string;
	params: Record<string, unknown>;
}

const panel = css({ marginBlock: "0.75rem", display: "grid", gap: "0.75rem", border: "1px solid var(--border)", borderRadius: "0.75rem", background: "var(--background)", padding: "1rem" });
const section = css({ display: "grid", gap: "0.625rem", borderTop: "1px solid var(--border)", paddingTop: "0.75rem", _first: { borderTop: "none", paddingTop: 0 } });
const button = css({ minHeight: "2.5rem", border: "1px solid var(--border)", borderRadius: "0.5rem", paddingInline: "0.75rem", fontSize: "0.8125rem", fontWeight: 600, cursor: "pointer", _hover: { background: "var(--muted)" }, _focusVisible: { outline: "2px solid var(--ring)", outlineOffset: "2px" } });
const input = css({ width: "100%", minHeight: "2.5rem", border: "1px solid var(--border)", borderRadius: "0.5rem", background: "var(--background)", padding: "0.625rem", color: "var(--foreground)" });

export function SharedUiDocumentRenderer({ document, onAction }: { document: UiDocument; onAction?: (event: SharedUiActionEvent) => void }) {
	return <section className={panel} data-shared-openui-document={document.id} data-openui-revision={document.revision}>
		{document.title ? <h3 className={css({ fontSize: "1rem", fontWeight: 700 })}>{document.title}</h3> : null}
		{document.description ? <p className={css({ color: "var(--muted-foreground)", fontSize: "0.8125rem" })}>{document.description}</p> : null}
		{document.nodes.map((node) => <SharedNode key={node.id} node={node} onAction={onAction} />)}
	</section>;
}

function SharedNode({ node, onAction }: { node: UiDocumentNode; onAction?: (event: SharedUiActionEvent) => void }) {
	if (node.type === "markdown") return <div className={section}><MarkdownBlock content={node.markdown} /></div>;
	if (node.type === "callout") return <aside className={css({ ...section.raw(), borderLeft: "3px solid var(--primary)", paddingLeft: "0.75rem" })} data-callout-tone={node.tone}>
		<strong>{node.title ?? node.tone}</strong><MarkdownBlock content={node.markdown} />
	</aside>;
	if (node.type === "question") return <Question node={node} onAction={onAction} />;
	if (node.type === "quiz") return <div className={section}><h4 className={css({ fontWeight: 700 })}>{node.title}</h4>{node.questions.map((question) => <Question key={question.id} node={question} onAction={onAction} />)}</div>;
	if (node.type === "goal") return <Checklist title={node.title} items={node.steps.map((step) => ({ id: step.id, title: step.title, done: step.status === "done" }))} actionType="complete-goal-step" onAction={onAction} />;
	if (node.type === "deck") return <Deck node={node} onAction={onAction} />;
	if (node.type === "study-plan") return node.items ? <Plan title={node.title ?? "Study plan"} overview={node.overview} items={node.items} onAction={onAction} /> : <Resource title={node.resource?.title ?? "Study plan"} content={node.resource?.content} uri={node.resource?.uri} />;
	if (node.type === "artifact") return <Resource title={node.resource.title} content={node.resource.content} uri={node.resource.uri} markdown={node.resource.format === "markdown"} />;
	if (node.type === "concept-map") return <div className={section}>{node.title ? <h4 className={css({ fontWeight: 700 })}>{node.title}</h4> : null}<MermaidRenderer code={node.source} /></div>;
	if (node.type === "notes") return <Notes node={node} onAction={onAction} />;
	if (node.type === "image") return <figure className={section}><img src={node.resource.uri} alt={node.alt} className={css({ maxWidth: "100%", borderRadius: "0.5rem" })} /><figcaption>{node.resource.title}</figcaption></figure>;
	if (node.type === "media") return <Media node={node} />;
	return <div className={section}><strong>Continue on {node.target}</strong><p>{node.reason}</p><p className={css({ color: "var(--muted-foreground)" })}>{node.context}</p>{node.target === "web" ? <a className={button} href="/">Open Keating web</a> : null}</div>;
}

function Question({ node, onAction }: { node: UiQuestion; onAction?: (event: SharedUiActionEvent) => void }) {
	const [answer, setAnswer] = useState("");
	const [selected, setSelected] = useState<string[]>([]);
	const multiple = node.multiSelect || node.kind === "multi_select";
	const submit = () => onAction?.({ type: "submit_answer", humanFriendlyMessage: `Answered: ${node.prompt}`, params: { nodeId: node.id, answer: node.choices ? selected : answer } });
	return <fieldset className={section} data-question-kind={node.kind ?? "text"}>
		<legend className={css({ fontWeight: 650 })}>{node.header ?? node.prompt}</legend>
		{node.header ? <p>{node.prompt}</p> : null}
		{node.choices ? <div className={css({ display: "grid", gap: "0.375rem" })}>{node.choices.map((choice) => <label key={choice.id} className={css({ display: "flex", alignItems: "center", gap: "0.5rem" })}><input type={multiple ? "checkbox" : "radio"} name={node.id} checked={selected.includes(choice.id)} onChange={() => setSelected((current) => multiple ? current.includes(choice.id) ? current.filter((id) => id !== choice.id) : [...current, choice.id] : [choice.id])} />{choice.label}</label>)}</div>
			: <textarea className={input} value={answer} onChange={(event) => setAnswer(event.currentTarget.value)} placeholder={node.blanks?.[0]?.placeholder ?? "Type your answer"} />}
		{node.hint ? <small>{node.hint}</small> : null}
		<button className={button} type="button" disabled={node.choices ? selected.length === 0 : answer.trim().length === 0} onClick={submit}>Submit answer</button>
	</fieldset>;
}

function Checklist({ title, items, actionType, onAction }: { title: string; items: Array<{ id: string; title: string; done: boolean }>; actionType: string; onAction?: (event: SharedUiActionEvent) => void }) {
	const [done, setDone] = useState(() => new Set(items.filter((item) => item.done).map((item) => item.id)));
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{title}</h4>{items.map((item) => <label key={item.id} className={css({ display: "flex", gap: "0.5rem" })}><input type="checkbox" checked={done.has(item.id)} onChange={() => { const next = new Set(done); next.has(item.id) ? next.delete(item.id) : next.add(item.id); setDone(next); onAction?.({ type: actionType, humanFriendlyMessage: `${next.has(item.id) ? "Completed" : "Reopened"}: ${item.title}`, params: { itemId: item.id, completed: next.has(item.id) } }); }} />{item.title}</label>)}</div>;
}

function Plan({ title, overview, items, onAction }: { title: string; overview?: string; items: UiStudyPlanItem[]; onAction?: (event: SharedUiActionEvent) => void }) {
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{title}</h4>{overview ? <MarkdownBlock content={overview} /> : null}<PlanItems items={items} onAction={onAction} /></div>;
}

function PlanItems({ items, onAction }: { items: UiStudyPlanItem[]; onAction?: (event: SharedUiActionEvent) => void }) {
	return <ul className={css({ display: "grid", gap: "0.5rem", paddingLeft: "1rem" })}>{items.map((item) => <li key={item.id}><Checklist title={item.title} items={[{ id: item.id, title: item.detail ?? item.title, done: item.status === "done" }]} actionType="complete-plan-item" onAction={onAction} />{item.children ? <PlanItems items={item.children} onAction={onAction} /> : null}</li>)}</ul>;
}

function Notes({ node, onAction }: { node: Extract<UiDocumentNode, { type: "notes" }>; onAction?: (event: SharedUiActionEvent) => void }) {
	const [value, setValue] = useState(node.value);
	return <div className={section}><label htmlFor={node.id} className={css({ fontWeight: 700 })}>{node.title}</label><textarea id={node.id} className={input} value={value} placeholder={node.placeholder} onChange={(event) => setValue(event.currentTarget.value)} /><button className={button} type="button" onClick={() => onAction?.({ type: "update-notes", humanFriendlyMessage: `Updated ${node.title}`, params: { nodeId: node.id, value } })}>Save notes</button></div>;
}

function Deck({ node, onAction }: { node: Extract<UiDocumentNode, { type: "deck" }>; onAction?: (event: SharedUiActionEvent) => void }) {
	const [index, setIndex] = useState(0);
	const [revealed, setRevealed] = useState(false);
	const card = node.cards[index];
	if (!card) return <div className={section}>This deck has no cards.</div>;
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{node.title}</h4><button className={button} type="button" onClick={() => setRevealed((value) => !value)}>{revealed ? card.back : card.front}</button>{revealed ? <div className={css({ display: "flex", flexWrap: "wrap", gap: "0.375rem" })}>{["Again", "Hard", "Good", "Easy"].map((label, rating) => <button key={label} className={button} type="button" onClick={() => { onAction?.({ type: "rate-card", humanFriendlyMessage: `${label}: ${card.front}`, params: { nodeId: node.id, cardId: card.id, rating } }); setRevealed(false); setIndex((index + 1) % node.cards.length); }}>{label}</button>)}</div> : null}</div>;
}

function Resource({ title, content, uri, markdown = false }: { title: string; content?: string; uri?: string; markdown?: boolean }) {
	return <div className={section}><h4 className={css({ fontWeight: 700 })}>{title}</h4>{content ? markdown ? <MarkdownBlock content={content} /> : <pre className={css({ overflowX: "auto", whiteSpace: "pre-wrap" })}>{content}</pre> : null}{uri ? <a className={button} href={uri} target="_blank" rel="noreferrer">Open resource</a> : null}</div>;
}

function Media({ node }: { node: Extract<UiDocumentNode, { type: "media" }> }) {
	if (node.kind === "audio") return <div className={section}><strong>{node.resource.title}</strong><audio controls src={node.resource.uri} /></div>;
	if (node.kind === "video") return <div className={section}><strong>{node.resource.title}</strong><video controls src={node.resource.uri} className={css({ maxWidth: "100%" })} /></div>;
	return <Resource title={node.resource.title} uri={node.resource.uri} content="Animation opens only from its validated resource URL." />;
}

