	test("migrates only notes and true valid leaf progress, preserving legacy state", () => {
		const storage = new MemoryStorage();
		const legacyPayload = JSON.stringify({
			version: 1,
			updatedAt: Date.parse("2026-08-11T02:00:00.000Z"),
			state: {
